import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { SplitButtonProps } from "./split-button.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "SplitButton";

export const SplitButtonClasses = {
  root: "exp-textura_split-button",
  leading: "exp-textura_split-button_leading",
  trailing: "exp-textura_split-button_trailing",
  sm: "exp-textura_split-button_sm",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  secondary: {
    root: {
      gap: "unset",
    },
    leadingButton: {
      backgroundColor: theme.buttonSplit.secondary.color.background.enabled,
      color: theme.buttonSplit.secondary.color.content.enabled,
      borderColor: theme.buttonSplit.secondary.color.border.enabled,
    },
    leadingButtonHover: {
      backgroundColor: theme.buttonSplit.secondary.color.background.hover,
      color: theme.buttonSplit.secondary.color.content.hover,
      borderColor: theme.buttonSplit.secondary.color.border.hover,
    },
    leadingButtonPressed: {
      backgroundColor: theme.buttonSplit.secondary.color.background.pressed,
      color: theme.buttonSplit.secondary.color.content.pressed,
      borderColor: theme.buttonSplit.secondary.color.border.pressed,
    },
    leadingButtonDisabled: {
      backgroundColor: theme.buttonSplit.secondary.color.background.disabled,
      color: theme.buttonSplit.secondary.color.content.disabled,
      borderColor: theme.buttonSplit.secondary.color.border.disabled,
    },
    trailingButton: {
      backgroundColor: theme.buttonSplit.secondary.color.background.enabled,
      color: theme.buttonSplit.secondary.color.content.enabled,
      borderColor: theme.buttonSplit.secondary.color.border.enabled,
    },
    trailingButtonHover: {
      backgroundColor: theme.buttonSplit.secondary.color.background.hover,
      color: theme.buttonSplit.secondary.color.content.hover,
      borderColor: theme.buttonSplit.secondary.color.border.hover,
    },
    trailingButtonPressed: {
      backgroundColor: theme.buttonSplit.secondary.color.background.pressed,
      color: theme.buttonSplit.secondary.color.content.pressed,
      borderColor: theme.buttonSplit.secondary.color.border.pressed,
    },
    trailingButtonDisabled: {
      backgroundColor: theme.buttonSplit.secondary.color.background.disabled,
      color: theme.buttonSplit.secondary.color.content.disabled,
      borderColor: theme.buttonSplit.secondary.color.border.disabled,
    },
  },
});

const generateStyles = (props: SplitButtonProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SplitButtonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",
    position: "relative",
    gap: 2,

    [`& .${SplitButtonClasses.leading}`]: {
      position: "relative",
      height: theme.toRem(32),
      ...theme.typography.label.md,
      padding: `0 ${theme.toRem(theme.spacing[16])}`,
      backgroundColor: theme.buttonSplit.primary.color.background.enabled,
      color: theme.buttonSplit.primary.color.content.enabled,
      borderColor: theme.buttonSplit.primary.color.border.enabled,
      ":dir(ltr)": {
        borderTopRightRadius: 0,
        borderBottomRightRadius: 0,
      },
      ":dir(rtl)": {
        borderTopLeftRadius: 0,
        borderBottomLeftRadius: 0,
      },
      "&:hover": {
        zIndex: 1,
        backgroundColor: theme.buttonSplit.primary.color.background.hover,
        color: theme.buttonSplit.primary.color.content.hover,
        borderColor: theme.buttonSplit.primary.color.border.hover,
        ...styleSlots?.leadingButtonHover,
      },
      "&:active": {
        backgroundColor: theme.buttonSplit.primary.color.background.pressed,
        color: theme.buttonSplit.primary.color.content.pressed,
        borderColor: theme.buttonSplit.primary.color.border.pressed,
        ...styleSlots?.leadingButtonPressed,
      },
      "&:disabled, &:disabled:hover": {
        backgroundColor: theme.buttonSplit.primary.color.background.disabled,
        color: theme.buttonSplit.primary.color.content.disabled,
        borderColor: theme.buttonSplit.primary.color.border.disabled,
        ...styleSlots?.leadingButtonDisabled,
      },
      ...styleSlots?.leadingButton,
    },
    [`& .${SplitButtonClasses.trailing}`]: {
      position: "relative",
      marginLeft: theme.toRem(-1),
      height: theme.toRem(32),
      ...theme.typography.label.md,
      padding: `0 ${theme.toRem(theme.spacing[8])}`,
      minWidth: theme.toRem(32),
      backgroundColor: theme.buttonSplit.primary.color.background.enabled,
      color: theme.buttonSplit.primary.color.content.enabled,
      borderColor: theme.buttonSplit.primary.color.border.enabled,
      ":dir(ltr)": {
        borderTopLeftRadius: 0,
        borderBottomLeftRadius: 0,
      },
      ":dir(rtl)": {
        borderTopRightRadius: 0,
        borderBottomRightRadius: 0,
      },
      "&:hover": {
        zIndex: 1,
        backgroundColor: theme.buttonSplit.primary.color.background.hover,
        color: theme.buttonSplit.primary.color.content.hover,
        borderColor: theme.buttonSplit.primary.color.border.hover,
        ...styleSlots?.trailingButtonHover,
      },
      "&:active": {
        backgroundColor: theme.buttonSplit.primary.color.background.pressed,
        color: theme.buttonSplit.primary.color.content.pressed,
        borderColor: theme.buttonSplit.primary.color.border.pressed,
        ...styleSlots?.trailingButtonPressed,
      },
      "&:disabled, &:disabled:hover": {
        backgroundColor: theme.buttonSplit.primary.color.background.disabled,
        color: theme.buttonSplit.primary.color.content.disabled,
        borderColor: theme.buttonSplit.primary.color.border.disabled,
        ...styleSlots?.trailingButtonDisabled,
      },
      ...styleSlots?.trailingButton,
    },
    [`&.${SplitButtonClasses.sm}`]: {
      [`& .${SplitButtonClasses.leading}`]: {
        height: theme.toRem(24),
        ...theme.typography.label.sm,
        padding: `0 ${theme.toRem(theme.spacing[8])}`,
        ...styleSlots?.leadingButtonSm,
      },
      [`& .${SplitButtonClasses.trailing}`]: {
        height: theme.toRem(24),
        ...theme.typography.label.sm,
        padding: `0 ${theme.toRem(theme.spacing[4])}`,
        minWidth: theme.toRem(24),
        ...styleSlots?.trailingButtonSm,
      },
    },
    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledSplitButton = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SplitButtonProps>((props) => generateStyles(props));
